}



/** ⏱️Masks line and nested block comments after literals have been masked, preserving block depth across lines. */
function interactivityMaskComments(raw: string, initialDepth: number): { code: string; depth: number } {
  const masked = policyMaskLiterals(raw);
  let code = "";
  let depth = initialDepth;
  let index = 0;
  while (index < masked.length) {
    const pair = masked.slice(index, index + 2);
    if (depth > 0) {
      if (pair === "/*") {
        depth += 1;
        index += 2;
      } else if (pair === "*/") {
        depth -= 1;
        index += 2;
      } else {
        index += 1;
      }
      continue;
    }
    if (pair === "//") break;
    if (pair === "/*") {
      depth = 1;
      index += 2;
      continue;
    }
    code += masked[index];
    index += 1;
  }
  return { code, depth };
}

/** 🧪️Brace-spans of any free item guarded by a `cfg` expression containing `test`. */
/** 🧩️ What a `#[cfg(test)]` attribute's same-line remainder starts: a parameter, field or argument (`hook: T,`, `hook: T) -> R {`)
 * ends at a top-level `,` or an unmatched `)`/`]` and leaves its enclosing item in production; anything else is the item itself. */
function interactivityCfgTestSameLineKind(item: string): "member" | "item" {
  let depth = 0;
  for (const char of item) {
    if (char === "(" || char === "[") depth++;
    else if (char === ")" || char === "]") {
      if (depth === 0) return "member";
      depth--;
    } else if (depth === 0 && char === ",") return "member";
    else if (depth === 0 && (char === "{" || char === ";")) return "item";
  }
  return "item";
}

/** 🧪️ The line spans of `#[cfg(test)]` items — an attribute that names `test` without negating it (`cfg(not(test))` is production) —
 * whether the item starts on the attribute's own line (`#[cfg(test)] hook: T,`, `#[cfg(test)] if armed {`) or on a later one. A
 * test-only parameter or field (`,`) keeps its enclosing production item. */
function interactivityCfgTestItemSpans(lines: readonly string[]): PolicyModSpan[] {
  const spans: PolicyModSpan[] = [];
  const stack: { startLine: number; depth: number }[] = [];
  let pendingStart: number | undefined;
  let depth = 0;
  lines.forEach((raw, i) => {
    const codeOnly = policyMaskLiterals(raw).replace(/\/\/.*$/, "");
    const attribute = /#\[cfg\((?![^\]]*\bnot\s*\()[^\]]*\btest\b[^\]]*\)\]/.exec(codeOnly);
    if (attribute) pendingStart = i + 1;
    const sameLine = pendingStart === i + 1 && attribute ? codeOnly.slice(attribute.index + attribute[0].length) : "";
    if (sameLine.trim().length > 0 && !/^\s*#\[/.test(sameLine) && interactivityCfgTestSameLineKind(sameLine) === "member") pendingStart = undefined;
    const item = pendingStart === undefined ? "" : i + 1 > pendingStart ? codeOnly : sameLine;
    if (pendingStart !== undefined && item.trim().length > 0 && !/^\s*#\[/.test(item)) {
      const openCount = (item.match(/\{/g) ?? []).length;
      if (openCount > 0) {
        stack.push({ startLine: pendingStart, depth });
        pendingStart = undefined;
      } else if (/;\s*$/.test(item)) {
        spans.push({ name: "cfg(test)", startLine: pendingStart, endLine: i + 1 });
        pendingStart = undefined;
      } else if (/,\s*$/.test(item)) {
        pendingStart = undefined;
      }
    }
    depth += (codeOnly.match(/\{/g) ?? []).length - (codeOnly.match(/\}/g) ?? []).length;
    while (stack.length > 0 && depth <= stack[stack.length - 1]!.depth) {
      const top = stack.pop()!;
      spans.push({ name: "cfg(test)", startLine: top.startLine, endLine: i + 1 });
    }
  });
  return spans;
}

/** ⏱️Scans one file's lines for `patterns`, skipping `#[cfg(test)] mod … { … }` bodies — matches this repo's own R4 precedent that a test module is a sanctioned executor/blocking entry point, and keeps the audit signal free of unit-test noise unrelated to the UI-thread interactivity goal. */
function interactivityScanFile(repoRoot: string, relPath: string, patterns: readonly InteractivityAuditPatternDef[]): InteractivityFinding[] {
  const content = policyReadFileSafe(repoRoot, relPath);
  if (!content) return [];
  const findings: InteractivityFinding[] = [];
  const lines = content.split(/\r?\n/);
  const testSpans = [...policyTestModSpans(lines), ...interactivityCfgTestItemSpans(lines)];
  let blockCommentDepth = 0;
  lines.forEach((raw, i) => {
    const lineNo = i + 1;
    const masked = interactivityMaskComments(raw, blockCommentDepth);
    blockCommentDepth = masked.depth;
    if (policyLineInTestMod(testSpans, lineNo)) return;
    const codeOnly = masked.code;
    for (const pattern of patterns) {
      if (pattern.re.test(codeOnly)) findings.push({ category: pattern.category, file: relPath, line: lineNo, text: raw.trim().slice(0, 200) });
    }
  });
  return findings;
}

/** ⏱️Full forbidden-call scan: `blocking-bridge`/`sync-*` categories over [[INTERACTIVITY_AUDIT_UI_ROOTS]]; `thread-pool` over [[INTERACTIVITY_AUDIT_PRODUCTION_ROOTS]] minus [[INTERACTIVITY_AUDIT_RUNTIME_SANCTIONED_ROOTS]]. */
function interactivityAuditScan(repoRoot: string): InteractivityFinding[] {
  interactivityRuntimeSourceSelfTests();
  const allRustFiles = policyWalkRelFiles(repoRoot, INTERACTIVITY_AUDIT_PRODUCTION_ROOTS, (_path, name) => name.endsWith(".rs")).filter(interactivityIsRuntimeSource);
  const uiPatterns = INTERACTIVITY_AUDIT_PATTERNS.filter((p) => p.scope === "ui");
  const runtimePatterns = INTERACTIVITY_AUDIT_PATTERNS.filter((p) => p.scope === "runtime-repo-wide");
  const findings: InteractivityFinding[] = [];
  for (const relPath of allRustFiles) {
    if (interactivityIsUiReachable(relPath) || interactivityIsExactBlockingBridgeFile(relPath)) findings.push(...interactivityScanFile(repoRoot, relPath, uiPatterns));
    if (!interactivityIsRuntimeSanctioned(relPath)) findings.push(...interactivityScanFile(repoRoot, relPath, runtimePatterns));
  }
  return findings;
}

