    "reason: SurfaceLayoutReason",
    "epoch: u64",
    "struct ThemePropagationCursor",
    "tokens: [Option<UiSurfaceToken>; UI_LAYOUT_SURFACE_SLOTS]",
    "ThemePropagationPhase::Validate",
