//#region 🔖️TestScript
/** 🎚️Nx target name for a level — `fundamental` keeps the bare `test` target; others get a `test-<level>` suffix. */
function testTargetForLevel(level: TestLevel): string {
  return level === "fundamental" ? "test" : `test-${level}`;
}

/**
 * 🔣️The SSOT taxonomy, read once. The root script must not know WHERE a module lives or WHICH
 * subcommands it offers — both are declared vocabulary, so adding a phase or relocating the testing
 * domain is a taxonomy edit and never an edit here.
 */
function repoTaxonomy(root: string): Record<string, unknown> {
  return JSON.parse(readFileSync(join(root, "🧰️framework/🛍️products/🦑️repo/🔨️modules/📚️library/🔣️taxonomy.json"), "utf8")) as Record<string, unknown>;
}


/**
 * 🧪️Root test router — a thin delegate.
 *
 * It resolves the level, resolves the scope, invokes Nx and enforces the gates. Everything that
 * knows what a test *is* (discovery, the feature contract, oracles, hosts, comparison, reports)
 * lives in the testing domain the taxonomy names; everything that knows how to *run a
 * process* stays in the repo library. No test phase is special-cased here any more, no `compose`
 * project is prebuilt, and no repository-wide Vitest aggregation is constructed.
 */
export class TestScript extends Script {
  async run(segments: string[]): Promise<void> {
    const { level, rest } = resolveTestLevel(segments);
    if (rest[0] === "storybook") {
      await this.runStorybookPlaywright();
      return;
    }
    if (rest[0] === "outcome-law-gate") {
      if (rest.length !== 1) throw new Error("Expected test outcome-law-gate");
      await runRepositoryTestCommand(process.execPath, ["test", join(this.root, "🧪️tests/🧪️outcome-law-gate/🟦️.ts")], { cwd: this.root });
      return;
    }
    if (rest[0] === "repo-client") {
      await this.runRepoGoTest(`./${REPO_CLIENT_GO}`, level, rest.slice(1));
      return;
    }
    if (rest[0] === "repo-mcp") {
      await this.runRepoGoTest(`./${REPO_MCP_GO}`, level, rest.slice(1));
      const mcpOut = resolveMcpBin(this.root);
      runCanonicalGoBuild(join(this.root, REPO_MCP_GO), ["-o", mcpOut, "."], {
        env: { ...process.env, GOWORK: join(this.root, "go.work") },
        budgetMs: buildBudgetMs(),
      });
      await this.runRepoGoTest(`./${REPO_CLIENT_GO}`, level, ["-run", "Mcp|MCP|mcp", ...rest.slice(1)]);
      return;
    }
    // 🧪️ Owner-root test phases, routed through the testing domain's own router.
    // 🎚️Both `test quick parity` and `test parity quick` must mean the same run. The first form is
    // already resolved above (and exported through SEMIO_TEST_LEVEL); the second is resolved over the
    // segments that FOLLOW the phase word. Which phases exist, and where the router that serves them
    // lives, are both taxonomy vocabulary — this file never enumerates either.
    const taxonomy = repoTaxonomy(this.root);
    const domain = String(taxonomy.testDomainPath ?? "");
    const phases = (taxonomy.testPhases ?? []) as string[];
    const levelless = (taxonomy.testLevellessPhases ?? []) as string[];
    const phase = rest[0] ?? "";
    if (domain !== "" && phases.includes(phase)) {
      const { level: phaseLevel, rest: phaseArgs } = resolveTestLevel(rest.slice(1));
      runCmd("bun", [join(this.root, domain, "📜️script.ts"), phase, ...(levelless.includes(phase) ? [] : [phaseLevel]), ...phaseArgs], { cwd: join(this.root, domain), ...orchestratorBudgetOpts() });
      return;
    }

    if (rest.length) throw new Error(`Unknown workspace test selection: ${rest.join(" ")}`);
    if (process.env.NX_TASK_TARGET_PROJECT !== "workspace") throw new Error(`test ${level} runs every project's tests as Nx prerequisites and asserts nothing on its own; run \`bun nx run workspace:${level === "fundamental" ? "test" : `test-${level}`}\``);
    if (level === "exhaustive" && coverageEnabled()) this.enforceCoverageGate();
    console.log(`[test] ${level} prerequisites completed through Nx`);
  }

  /** 📊️Walks every `*.lcov`/`lcov.info`/`coverage.info`/`*.cover` file under `.🧬semio/🦑️repo/📊️metrics/coverage/`, merges them into one repo-wide LCOV, writes `summary.json`, and hard-fails below the 95% threshold — the exhaustive-level gate. */
  private enforceCoverageGate(): void {
    const walk = (dir: string, matches: (name: string) => boolean, found: string[] = []): string[] => {
      if (!existsSync(dir)) return found;
      for (const entry of readdirSync(dir, { withFileTypes: true })) {
        const full = join(dir, entry.name);
        if (entry.isDirectory()) walk(full, matches, found);
        else if (matches(entry.name)) found.push(full);
      }
      return found;
    };
    const recordSets: LcovFileRecord[][] = [
      ...walk(coverageDir(this.root, "rust"), (n) => n.endsWith(".lcov")).map((f) => parseLcov(readFileSync(f, "utf8"))),
      ...walk(coverageDir(this.root, "js"), (n) => n === "lcov.info").map((f) => parseLcov(readFileSync(f, "utf8"))),
      ...walk(coverageDir(this.root, "py"), (n) => n.endsWith(".lcov")).map((f) => parseLcov(readFileSync(f, "utf8"))),
      ...walk(coverageDir(this.root, "dotnet"), (n) => n === "coverage.info").map((f) => parseLcov(readFileSync(f, "utf8"))),
      ...walk(coverageDir(this.root, "go"), (n) => n.endsWith(".cover")).map((f) => goProfileToLcov(readFileSync(f, "utf8"))),
    ];
    const merged = mergeLcov(recordSets);
    const summary = summarizeCoverage(merged);
    writeFileSync(join(getRepoMetaDir(this.root), "📊️metrics", "coverage", "lcov.info"), renderLcov(merged));
    writeFileSync(join(getRepoMetaDir(this.root), "📊️metrics", "coverage", "summary.json"), JSON.stringify(summary, null, 2));
    enforceCoverageThreshold(summary, 95);
  }

  private async waitForUrl(url: string, timeoutMs: number): Promise<void> {
    const start = Date.now();
    while (Date.now() - start < timeoutMs) {
      try {
        const response = await fetch(url);
        if (response.ok) return;
      } catch {
        /* retry */
      }
      await new Promise((resolve) => setTimeout(resolve, 500));
    }
    throw new Error(`Timed out waiting for ${url}`);
  }

  private isTcpPortFree(port: number, host: string): Promise<boolean> {
    return new Promise((resolve) => {
      const server = createServer();
      server.unref();
      server.once("error", () => resolve(false));
      server.listen(port, host, () => {
        server.close(() => resolve(true));
      });
    });
  }

  private async pickStorybookStaticPort(preferred: number, span: number): Promise<number> {
    for (let port = preferred; port < preferred + span; port += 1) {
      if (await this.isTcpPortFree(port, "0.0.0.0")) return port;
    }
    throw new Error(`No free TCP port in ${preferred}..${preferred + span - 1}`);
  }

  /** ⏱️`goLevelTestArgs` keeps `-short` (skipping the `testing.Short()`-gated real-monorepo-scan tests in `repo/client/cli/go/main_test.go`) through `quick` and adds a cumulative `-skip` above the requested level. */
  private async runRepoGoTest(module: string, level: TestLevel, extraArgs: string[]): Promise<void> {
    await runCanonicalGoTests(join(this.root, module), [...goLevelTestArgs(level), ...goCoverageArgs(this.root, module), ...extraArgs], {
      env: { ...process.env, GOWORK: join(this.root, "go.work") },
    });
  }

  private async runStorybookPlaywright(): Promise<void> {
    const preferred = Number(process.env.STORYBOOK_PORT ?? 6010);
    const storybookPort = String(await this.pickStorybookStaticPort(preferred, 50));
    const baseUrl = `http://127.0.0.1:${storybookPort}/`;
    runCmd("bun", [join(this.root, "📜️script.ts"), "build", "storybook"], { cwd: this.root, ...orchestratorBudgetOpts() });
    const server = spawnDaemon("bun", [join(this.root, "📜️script.ts"), "dev", "storybook-static"], {
      cwd: this.root,
      env: { ...process.env, STORYBOOK_PORT: storybookPort },
    });
    try {
      await this.waitForUrl(new URL("🌐️.html", baseUrl).href, 120000);
      runCmd(process.execPath, ["x", "playwright", "test", "--config", ".storybook/🧪️tests/🧪️browser-runner/🟦️.ts"], {
        cwd: this.root,
        env: {
          ...process.env,
          PLAYWRIGHT_BASE_URL: baseUrl,
          PLAYWRIGHT_BROWSERS_PATH: process.env.PLAYWRIGHT_BROWSERS_PATH ?? repoCacheDirectory(this.root, "tools", "ms-playwright"),
          STORYBOOK_PORT: storybookPort,
        },
      });
    } finally {
      server.kill();
    }
  }
}
