        scope: artRel,
        priority: "low",
        reason: "Shrink-only allowlists must be pruned as soon as the underlying file is fixed.",
        solution: `Remove "${key}" from POLICY_FIXTURE_HONESTY_ALLOWLIST.`,
      });
    }
  }
  return breaches;
}

